(o/definst voice [freq 440 amp 0.043 dur 0.75]
  (* amp (o/env-gen (o/perc 0.008 dur)) (o/mix [(o/sin-osc freq) (* 0.18 (o/sin-osc (* freq 2.01)))])))
(def metro (o/metronome 122))
(av/session
  (av/pattern :melody 8
    (o/play
      (o/at (metro 0) (voice :freq (o/midi->hz 74)))
      (o/at (metro 1) (voice :freq (o/midi->hz 77)))
      (o/at (metro 2.5) (voice :freq (o/midi->hz 81)))
      (o/at (metro 4) (voice :freq (o/midi->hz 84)))
      (o/at (metro 5.5) (voice :freq (o/midi->hz 81)))
      (o/at (metro 6.5) (voice :freq (o/midi->hz 76)))))
  (av/scene :cathedral {:shader "// Original live-set variation: folded chromatic architecture.
uniform float iBeat;
uniform float iZoom;
uniform float iIntensity;
uniform float iSymmetry;
uniform float iFeedback;
uniform float iPalette;
#define PI 3.14159265359
float edge(float d,float w){return w/(abs(d)+w);}
mat2 turn(float a){return mat2(cos(a),-sin(a),sin(a),cos(a));}
vec3 ink(float p){return .55+.45*cos(6.28318*(vec3(.03,.28,.55)+p));}
void mainImage(out vec4 c,in vec2 coord){
 vec2 uv=(coord-.5*iResolution.xy)/iResolution.y;
 float low=iAudioBass,hit=iAudioOnset,mid=iAudioMid,t=iGlobalTime;
 vec2 p=turn(t*.06+floor(iBeat/16.)*.16)*uv*(1.-iZoom-low*.12);
 float r=length(p),a=atan(p.y,p.x),n=max(3.,iSymmetry);
 float fold=abs(mod(a+PI/n,2.*PI/n)-PI/n);
 vec2 k=r*vec2(cos(fold),sin(fold));
 vec3 light=vec3(0.);
 for(int j=0;j<8;j++){
  float f=float(j),z=fract(f/8.+t*.052),radius=.06+z*z*.88;
  float d=k.x-radius-.05*sin(k.y*13.+t*.4+f);
  vec3 col=ink(f*.105+t*.008+iPalette*.3);
  light+=col*pow(edge(d,.0016+.003*hit),1.7)*(.3+z)*(.3+low*1.8);
  light+=col*edge(k.y-k.x*(.22+.06*sin(t*.3+f)),.0012)*edge(r-radius,.025)*mid*1.3;
 }
 float spoke=edge(sin(a*n+sin(r*10.-t)*.18),.015)*smoothstep(.08,.3,r);
 light+=vec3(.05,.85,.9)*spoke*(.08+iAudioHigh*.45);
 light*=1.-smoothstep(.65,.95,r);
 light=1.-exp(-light*(iIntensity+.3));
 light=mix(light,texture2D(iChannel1,coord/iResolution.xy).rgb,clamp(iFeedback,0.,.6));
 c=vec4(light,1.);
}
" :mappings {:zoom {:signal [:stem :bass :level] :amount 0.18}}}) (av/launch :cathedral {:transition :iris :beats 8}) (av/variation {:density 0.85 :seed 117}) (av/visual {:intensity 1.25 :symmetry 8 :feedback 0.12}))

(o/definst voice [freq 440 amp 0.038 dur 0.8]
  (* amp (o/env-gen (o/perc 0.008 dur)) (o/mix [(o/sin-osc freq) (* 0.18 (o/sin-osc (* freq 2.01)))])))
(def metro (o/metronome 122))
(av/session
  (av/pattern :melody 8
    (o/play
      (o/at (metro 0) (voice :freq (o/midi->hz 74)))
      (o/at (metro 1.5) (voice :freq (o/midi->hz 77)))
      (o/at (metro 3) (voice :freq (o/midi->hz 79)))
      (o/at (metro 4.5) (voice :freq (o/midi->hz 81)))
      (o/at (metro 6) (voice :freq (o/midi->hz 76)))
      (o/at (metro 7.5) (voice :freq (o/midi->hz 72)))))
  (av/scene :current {:shader "// Original live-set variation: interference printed on moving water.
uniform float iBeat;
uniform float iZoom;
uniform float iIntensity;
uniform float iFeedback;
uniform float iPalette;
mat2 turn(float a){return mat2(cos(a),-sin(a),sin(a),cos(a));}
void mainImage(out vec4 c,in vec2 coord){
 vec2 uv=(coord-.5*iResolution.xy)/iResolution.y;
 float t=iGlobalTime,low=iAudioBass,mid=iAudioMid,hit=iAudioOnset;
 vec2 p=uv*(1.-iZoom-low*.1);
 vec2 q=turn(.35*sin(t*.07))*p;
 float bend=.09*sin(q.x*7.+t*.3)+.07*sin(q.x*12.-t*.18);
 float carrier=sin((q.y+bend)*110.+t*.8);
 vec2 v=turn(-.22+t*.012)*p;
 float cross=sin((v.y+.06*sin(v.x*11.+t*.2))*104.-t*.7);
 float printA=pow(max(0.,carrier),14.);
 float printB=pow(max(0.,cross),14.);
 float envelope=.28+.72*exp(-abs(p.y)*1.6);
 vec3 light=vec3(.04,.86,.83)*printA*(.18+mid)*envelope;
 light+=vec3(1.,.18,.3)*printB*(.1+low*.9)*envelope;
 float ripples=pow(max(0.,sin(length(p)*86.-t*2.-low*5.)),28.);
 light+=vec3(.6,.3,1.)*ripples*hit*.3;
 light*=1.-smoothstep(.35,1.,length(p));
 light=1.-exp(-light*(iIntensity+1.));
 light=mix(light,light.brg,clamp(iPalette,0.,1.));
 light=mix(light,texture2D(iChannel1,coord/iResolution.xy).rgb,clamp(iFeedback,0.,.6));
 c=vec4(light,1.);
}
" :mappings {:zoom {:signal [:deck :b :bass] :amount 0.18}}}) (av/gesture :drop) (av/configure {:deck-b 0.85}) (av/launch :current {:transition :dissolve :beats 4}) (av/layer nil 0) (av/visual {:intensity 1.2 :palette 0.15 :feedback 0.1}))
